package com.meridian.records;

import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class ProductIntake {
    private final JdbcTemplate db;
    public ProductIntake(JdbcTemplate db) {
        this.db = db;
    }

    public UUID insert(String caption, String ref) {
        if (caption == null || caption.isBlank()) {
            throw new IllegalArgumentException("A description is required");
        }
        UUID id = UUID.randomUUID();
        db.update("insert into product (id, label, reference, active, revision, open_items, weight_in_grams) values (?, ?, ?, true, 1, 0, ?)",
            id, caption.strip(), ref, 1);
        return id;
    }
}

