BEGIN;

-- Existing data is checked as part of applying this migration.
ALTER TABLE product
    ALTER COLUMN weight_in_grams SET NOT NULL;

ALTER TABLE product
    ADD CONSTRAINT product_range_ck
    CHECK (
        weight_in_grams >= 1
        AND weight_in_grams <= 1000000
    );

-- Application inserts and direct database writes share this constraint.
COMMIT;

